package android.view;
import android.content.Context;import java.util.*;
public class View {public static boolean throwRemoveLayout,throwRemoveAttach;public static final int NO_ID=-1,IMPORTANT_FOR_ACCESSIBILITY_NO=2;static int next=10000;public static int generateViewId(){return ++next;}
 public interface OnAttachStateChangeListener{void onViewAttachedToWindow(View v);void onViewDetachedFromWindow(View v);}public interface OnLayoutChangeListener{void onLayoutChange(View v,int l,int t,int r,int b,int ol,int ot,int or,int ob);}
 public Object outlineProvider=new Object();public Object getOutlineProvider(){return outlineProvider;}public void setOutlineProvider(Object p){outlineProvider=p;}public final Context context;public ViewGroup parent;public ViewGroup.LayoutParams params;public int id=-1,accessibility,width=200,height=100;public boolean clip,attached=true;public float x,y,translationY;public final List<OnLayoutChangeListener> layouts=new ArrayList<>();public final List<OnAttachStateChangeListener> attaches=new ArrayList<>();
 public View(Context c){context=c;}public Context getContext(){return context;}public ViewParent getParent(){return parent;}public int getId(){return id;}public void setId(int v){id=v;}public void setClipToOutline(boolean v){clip=v;}public boolean getClipToOutline(){return clip;}public int getImportantForAccessibility(){return accessibility;}public void setImportantForAccessibility(int v){accessibility=v;}public ViewGroup.LayoutParams getLayoutParams(){return params;}public void setLayoutParams(ViewGroup.LayoutParams p){params=p;}public int getWidth(){return width;}public int getHeight(){return height;}public float getX(){return x;}public float getY(){return y;}public void setX(float v){x=v;}public void setY(float v){y=v;}public float getTranslationY(){return translationY;}public void setTranslationY(float v){translationY=v;}public boolean isAttachedToWindow(){return attached;}
 public void addOnLayoutChangeListener(OnLayoutChangeListener l){layouts.add(l);}public void removeOnLayoutChangeListener(OnLayoutChangeListener l){layouts.remove(l);if(throwRemoveLayout)throw new IllegalStateException("remove layout after write");}public void addOnAttachStateChangeListener(OnAttachStateChangeListener l){attaches.add(l);}public void removeOnAttachStateChangeListener(OnAttachStateChangeListener l){attaches.remove(l);if(throwRemoveAttach)throw new IllegalStateException("remove attach after write");}public void attach(boolean v){attached=v;for(var l:List.copyOf(attaches)){if(v)l.onViewAttachedToWindow(this);else l.onViewDetachedFromWindow(this);}}public void layout(int w,int h,float nx,float ny){width=w;height=h;x=nx;y=ny;for(var l:List.copyOf(layouts))l.onLayoutChange(this,0,0,w,h,0,0,0,0);}
 @SuppressWarnings("unchecked")public <T extends View>T findViewById(int v){return id==v?(T)this:null;}
}
